------------ LifeCycle ------------

function UIBattleEndRewardList:__init()
    self.rewardList = nil
    self.hasTreasure = nil
    self.flyGoodsMap = nil
    self.coShowGoodsFly = nil
end

function UIBattleEndRewardList:__delete()
    self.rewardList = nil
    self.hasTreasure = nil
    self.flyGoodsMap = nil
    self.coShowGoodsFly = nil
end

function UIBattleEndRewardList:Awake()
    self.Root_MissionRewardsList:InitGridView(0, Bind(self, self.OnGetItemByIndex))
    self.hasTreasure = false
    self.flyGoodsMap = {}
end

function UIBattleEndRewardList:Start()
end

function UIBattleEndRewardList:OnEnable()
    local animation = self.controller:GetComponent(typeof(CS.UnityEngine.Animation))
    if not isNull(animation) then
        animation:Play(self.hasTreasure and TreasureAnimation or NormalAnimation)
    end

    self:ShowGoodsFLy(1.2)
end

function UIBattleEndRewardList:OnDestroy()
    if isNotNull(self.coShowGoodsFly) then
        cs_coroutine.stop(self.coShowGoodsFly)
        self.coShowGoodsFly = nil
    end
    CfUtils.SetHealthNodesCanClick(true)    -- 还原资源栏按钮为可点击状态
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

