function UIBattleEndRewardList:SetHasTreasure(state)
    self.hasTreasure = state
end

function UIBattleEndRewardList:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local cell = gridView:NewListViewItem(GoodsNodePrefabName)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        -- 把需要飞翔特效的道具go记录下来
        local item = self.rewardList[index + 1]
        for i, targetId in ipairs(FlyGoodsId) do
            if item.goodsId == targetId then
                self.flyGoodsMap[targetId] = cell
            end
        end
    end
    cell.gameObject.name = string.format("%s%s", GoodsNodePrefabName, checkString(index + 1))
    local reScale = cell.gameObject:GetComponent(typeof(CS.Game.Native.Common.ReverseScale))
    reScale:ResetScale()
    local goodNodeMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)
    if not IsNull(goodNodeMB) then
        if IsNull(goodNodeMB.Env) then
            goodNodeMB:Init()
        end
        ---@type GoodNodeMB
        local env = goodNodeMB.Env
        local item = self.rewardList[index + 1]
        if isNull(item) then return cell end
        local _checkGoodsIdForSignNum = function(goodsId, goodsNum)
            local idType = GoodsUtils.GetIdType(goodsId)
            if idType == Constants.IDType.Equipment or idType == Constants.IDType.EquipmentCore then return end
            return goodsNum
        end
        local num = _checkGoodsIdForSignNum(item.goodsId, item.num)
        local goodsParaList = not IsNull(num) 
                and { goodsId = item.goodsId, isShowNo = true, text = string.format("x%s", checkInt(math.abs(num))), dojo = item.playerEquipment, superScript = item.from }
                or { goodsId = item.goodsId, text = tostring(num), dojo = item.playerEquipment, superScript = item.from }
        env:Reload(goodsParaList)
        -- env:SetSanXingFlagShow(isSet(item, "isStarReward") and item.isStarReward > 0)
        -- if isSet(item, "isStarReward") and item.isStarReward > 0 then
        --     env:SetBonusText(localize("三星奖励"),false, "#ffd646")
        -- end
        env:SetClickButtonAction(
                function(goodsId, uId)
                    GameUtils.ShowResultTips(cell.gameObject.transform:Find("Container"), goodsId, uId)
                end)
    end
    local cg = cell.gameObject:GetComponent(typeof(CanvasGroup))
    if isNotNull(cg) then
        cg.alpha = 1
    end
    return cell
end

