function UIBattleEndRewardList:SetRewardRootInfo()
    self.Txt_GetRewardDes.Status = 1
    self.Txt_GetRewardDes:Reset()
    self.rewardList = {}
    self.rewardList = checkTable(BattleEndMgr:GetBattleEndRewardsList())
    print("[奖励] 结算", table.dump(checkTable(self.rewardList)), nil, 3)
    GameUtils.ReloadData(self.Root_MissionRewardsList, #self.rewardList)
end

function UIBattleEndRewardList:SetReturnPlayerHP()
    self.Txt_GetRewardDes.Status = 2
    self.Txt_GetRewardDes:Reset()
    self.rewardList = {}
    local hpNum = BattleEndMgr:GetReturnPlayerHPValue()
    local hpData = { goodsId = Constants.Currency.HpId, num = hpNum }
    table.insert(self.rewardList, hpData)
    GameUtils.ReloadData(self.Root_MissionRewardsList, #self.rewardList)
end

function UIBattleEndRewardList:SetExtraReward()
    local extraRewards = BattleEndMgr:GetExtraRewardsList()
    if not isNull(extraRewards) and table.count(extraRewards) > 0 then
        local RT_ImgLine = self.Root_MissionRewardsList.transform:Find("Img_Line")
        KTool.SetActive(RT_ImgLine, false)
        KTool.SetActive(self.Txt_GetRewardDes, false)
        KTool.SetActive(self.RT_ExtraRewards, true)

        local goodsId = extraRewards[1].goodsId
        local goodsNum = extraRewards[1].num
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.Img_ExtraRewards:LoadSprite(vo.photoPath)
        self.Txt_ExtraRewards.text = string.format("x%d", checkInt(goodsNum))
    end
end

--- 需要飞翔特效的道具显示到资源栏上
---@param rewardList any
function UIBattleEndRewardList:ShowResourceBar(rewardList)
    local showIds = {}
    for i, reward in ipairs(rewardList) do
        for j, targetId in ipairs(FlyGoodsId) do
            if checkNumber(reward.goodsId) == targetId then
                table.insert(showIds, targetId)
            end
        end
    end

    if #showIds > 0 then
        local nav = CS.UINavigationBarRoot.Instance
        nav:SetActive(true)
        nav.orderTracker.ignoreParentTracker = true
        nav.orderTracker.addSortingOrder = 1055
        CfUtils.RefreshTopGoods(showIds)
        CfUtils.SetTopRightProjection(0)
        CfUtils.SetHealthNodesCanClick(false)
    end
end

function UIBattleEndRewardList:ShowGoodsFLy(delay)
    local flyRewards = {}
    local rewardList = self.rewardList
    -- 从奖励中找到需要飞的道具
    if isNotNull(rewardList) and table.count(rewardList) > 0 then
        for i, reward in ipairs(rewardList) do
            for j, targetId in ipairs(FlyGoodsId) do
                if checkNumber(reward.goodsId) == targetId then
                    local cell = self.flyGoodsMap[targetId]
                    if isNotNull(cell) then
                        table.insert(flyRewards, reward)
                    end
                end
            end
        end
    end
    -- 飞
    if #flyRewards > 0 then
        self.coShowGoodsFly = cs_coroutine.start(function()
            if delay and (checkNumber(delay) > 0) then
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(delay))
            end
            -- 显示资源条
            self:ShowResourceBar(rewardList)
            -- 飞
            local lastCo
            for i, reward in ipairs(flyRewards) do
                local targetId = checkNumber(reward.goodsId)
                local cell = self.flyGoodsMap[targetId]
                if isNotNull(cell) then
                    local go = GameObject("FlyGoods_"..tostring(targetId))
                    KTool.SetParent(go, self.controller.gameObject.transform.parent.parent.gameObject)
                    local RT_go = KTool.GetOrAddComponent(go, typeof(RectTransform))
                    RT_go.position = self:GetCenterPos(cell)
                    local isMore = reward.num > MaidCoffeeConstants.IsMoreGoodsNum[targetId]
                    lastCo = GameUtils.StartFlyGoods(go, targetId, isMore)
                end
            end
            -- 有多个飞行道具的时候，等最后一个就行
            if isNotNull(lastCo) then
                cs_coroutine.yield_return(lastCo)
            end
            self.coShowGoodsFly = nil
        end)
    end
end

--- 获取不受pivot影响的中心点坐标
---@param go any
function UIBattleEndRewardList:GetCenterPos(go)
    local rectTransform = go:GetComponent(typeof(RectTransform))
    local corners = Support.new_array(typeof(Unity_Vector3), 4)
    rectTransform:GetWorldCorners(corners)
    local center = (corners[0] + corners[1] + corners[2] + corners[3]) / 4;
    return center
end

